                mode === 'meeting'
                  ? 'bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/25 font-bold'
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50'
              }`}

export const MINUTES_PER_DAY = 24 * 60

const formatterCache = new Map<string, Intl.DateTimeFormat>()

function getFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = formatterCache.get(timeZone)
  if (!formatter) {
    formatter = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
    })
    formatterCache.set(timeZone, formatter)
  }
  return formatter
}

/**
 * UTC offset of `timeZone` at the given instant, in minutes (east-positive).
 * Derived from Intl so DST is handled by the runtime's tz database.
 */
export function getUtcOffsetMinutes(timeZone: string, at: Date = new Date()): number {
  const parts = getFormatter(timeZone).formatToParts(at)
  const read = (type: Intl.DateTimeFormatPartTypes) =>
    Number(parts.find((part) => part.type === type)?.value ?? 0)

  const asUtc = Date.UTC(
    read('year'),
    read('month') - 1,
    read('day'),
    read('hour') % 24,
    read('minute'),
    read('second'),
  )
  // Drop sub-second drift so the offset is an exact number of minutes.
  const instant = Math.floor(at.getTime() / 1000) * 1000
  return Math.round((asUtc - instant) / 60_000)
}

/** e.g. "UTC+5:30", "UTC-7", "UTC±0" */
export function formatUtcOffset(offsetMinutes: number): string {
  if (offsetMinutes === 0) return 'UTC±0'
  const sign = offsetMinutes > 0 ? '+' : '-'
  const abs = Math.abs(offsetMinutes)
  const hours = Math.floor(abs / 60)
  const minutes = abs % 60
  return `UTC${sign}${hours}${minutes ? `:${String(minutes).padStart(2, '0')}` : ''}`
}

/** Wrap a minute-of-day value into [0, 1440). */
export function wrapMinutes(minutes: number): number {
  return ((minutes % MINUTES_PER_DAY) + MINUTES_PER_DAY) % MINUTES_PER_DAY
}

/**
 * Local minute-of-day in a city when it is `referenceHour` o'clock in the
 * reference city.
 */
export function localMinuteOfDay(
  referenceHour: number,
  referenceOffset: number,
  cityOffset: number,
): number {
  return wrapMinutes(referenceHour * 60 + (cityOffset - referenceOffset))
}

export type TimeFormat = '12h' | '24h'

interface FormatHourOptions {
  /** Include ":mm" even when minutes are zero. */
  padded?: boolean
}

/** Format a minute-of-day value, e.g. 570 → "9:30am" / "09:30". */
export function formatMinuteOfDay(
  minuteOfDay: number,
  format: TimeFormat,
  { padded = false }: FormatHourOptions = {},
): string {
  const wrapped = wrapMinutes(minuteOfDay)
  const hours = Math.floor(wrapped / 60)
  const minutes = wrapped % 60
  const mm = String(minutes).padStart(2, '0')

  if (format === '24h') {
    return `${String(hours).padStart(2, '0')}:${mm}`
  }

  const suffix = hours < 12 ? 'am' : 'pm'
  const hour12 = hours % 12 === 0 ? 12 : hours % 12
  const showMinutes = padded || minutes !== 0
  return `${hour12}${showMinutes ? `:${mm}` : ''}${suffix}`
}

/** Short label for a whole hour used in select options and axis headers. */

import type { City } from '@/data/cities'
import { currentHourAtOffset, getUtcOffsetMinutes, localMinuteOfDay } from './timezone'

export type Mode = 'meeting' | 'base'

export interface AwakeWindow {
  /** Hour (0–23) the awake window starts, inclusive. */
  wakeHour: number
  /** Hour (0–23) the awake window ends, exclusive. */
  sleepHour: number
}

export type CellState = 'sleeping' | 'awake' | 'overlap'

export interface HourCell {
  /** Hour of the reference city's day (0–23) this cell belongs to. */
  referenceHour: number
  /** Local minute-of-day in this city at that reference hour. */
  localMinute: number
  state: CellState
}

export interface CityRow {
  city: City
  offsetMinutes: number
  isReference: boolean
  cells: HourCell[]
}

export interface HourRange {
  /** Inclusive start hour in reference time. */
  start: number
  /** Exclusive end hour in reference time; may exceed 23 when wrapping midnight. */
  end: number
}

export interface OverlapResult {
  hours: number[]
  ranges: HourRange[]
}

export interface Schedule {
  rows: CityRow[]
  /** The hour it is right now in the reference city, or null when no cities are selected. */
  currentReferenceHour: number | null
  /** Meeting mode: overlap shared by every city. */
  meeting: OverlapResult
  /** Base mode: overlap of each non-reference city with the reference, keyed by city id. */
  perCity: Map<string, OverlapResult>
}

export const HOURS = Array.from({ length: 24 }, (_, hour) => hour)

/**
 * Whether a local minute-of-day falls inside the awake window.
 * Supports overnight windows (wake 22 → sleep 6). Equal hours = always awake.
 */
export function isAwake(localMinute: number, { wakeHour, sleepHour }: AwakeWindow): boolean {
  const wake = wakeHour * 60
  const sleep = sleepHour * 60
  if (wake === sleep) return true
  if (wake < sleep) return localMinute >= wake && localMinute < sleep
  return localMinute >= wake || localMinute < sleep
}

/** Collapse a sorted list of hours into contiguous [start, end) ranges, merging across midnight. */
export function hoursToRanges(hours: number[]): HourRange[] {
  if (hours.length === 0) return []
  const sorted = [...new Set(hours)].sort((a, b) => a - b)
  if (sorted.length === 24) return [{ start: 0, end: 24 }]

  const ranges: HourRange[] = []
  let start = sorted[0]
  let previous = sorted[0]
  for (const hour of sorted.slice(1)) {
    if (hour === previous + 1) {
      previous = hour
      continue
    }
    ranges.push({ start, end: previous + 1 })
    start = hour
    previous = hour
  }
  ranges.push({ start, end: previous + 1 })

  // A range ending at midnight followed by one starting at 0 is one window that wraps.
  if (ranges.length > 1) {
    const first = ranges[0]
    const last = ranges[ranges.length - 1]
    if (first.start === 0 && last.end === 24) {
      ranges.pop()
      ranges.shift()
      ranges.push({ start: last.start, end: 24 + first.end })
    }
  }
  return ranges
}

function toResult(hours: number[]): OverlapResult {
  return { hours, ranges: hoursToRanges(hours) }

}

export function computeSchedule(
  cities: City[],
  window: AwakeWindow,
  mode: Mode,
  now: Date = new Date(),
): Schedule {
  if (cities.length === 0) {
    return { rows: [], currentReferenceHour: null, meeting: toResult([]), perCity: new Map() }
  }

  const offsets = cities.map((city) => getUtcOffsetMinutes(city.timeZone, now))
  const referenceOffset = offsets[0]

  const awakeMatrix = cities.map((_, index) =>
    HOURS.map((hour) => isAwake(localMinuteOfDay(hour, referenceOffset, offsets[index]), window)),
  )
  const referenceAwake = awakeMatrix[0]

  const meetingHours = HOURS.filter((hour) => awakeMatrix.every((row) => row[hour]))

  const perCity = new Map<string, OverlapResult>()
  for (let index = 1; index < cities.length; index++) {
    const hours = HOURS.filter((hour) => referenceAwake[hour] && awakeMatrix[index][hour])
    perCity.set(cities[index].id, toResult(hours))
  }

  // In base mode the reference row lights up wherever at least one colleague is reachable.
  const referenceBaseHours = new Set<number>()
  for (const result of perCity.values()) result.hours.forEach((hour) => referenceBaseHours.add(hour))

  const rows: CityRow[] = cities.map((city, index) => {
    const isReference = index === 0
    const highlighted: ReadonlySet<number> =
      mode === 'meeting'
        ? new Set(meetingHours)
        : isReference
          ? referenceBaseHours
          : new Set(perCity.get(city.id)?.hours ?? [])

    const cells: HourCell[] = HOURS.map((hour) => {
      const awake = awakeMatrix[index][hour]
      const state: CellState = !awake ? 'sleeping' : highlighted.has(hour) ? 'overlap' : 'awake'
      return {
        referenceHour: hour,
        localMinute: localMinuteOfDay(hour, referenceOffset, offsets[index]),
        state,
      }
    })

    return { city, offsetMinutes: offsets[index], isReference, cells }
  })

  return {
    rows,
    currentReferenceHour: currentHourAtOffset(referenceOffset, now),
    meeting: toResult(meetingHours),
    perCity,
  }
}

import { AlertTriangle, Users } from 'lucide-react'
import type { ReactNode } from 'react'
import { RangeBadges } from './RangeBadges'
import { Card } from './ui/Card'
import type { OverlapResult, Schedule } from '@/lib/overlap'
import type { TimeFormat } from '@/lib/timezone'
import { useAppStore } from '@/store/useAppStore'

interface OverlapSummaryProps {
  schedule: Schedule
}

export function OverlapSummary({ schedule }: OverlapSummaryProps) {
  const mode = useAppStore((state) => state.mode)
  const format = useAppStore((state) => state.settings.timeFormat)
  const reference = schedule.rows[0]

  if (!reference || schedule.rows.length < 2) return null

  return (
    <Card className="animate-fade-up p-5" aria-live="polite">
      <div className="mb-4 flex items-center justify-between gap-3">
        <h2 className="flex items-center gap-2 text-sm font-semibold text-ink-200">
          <Users className="h-4 w-4 text-ink-400" aria-hidden />
          {mode === 'meeting' ? 'Common availability' : `Availability with ${reference.city.name}`}
        </h2>
        <span className="text-xs text-ink-500">
          Times in <span className="font-medium text-ink-300">{reference.city.name}</span>
        </span>
      </div>

      {mode === 'meeting' ? (
        <MeetingSummary result={schedule.meeting} cityCount={schedule.rows.length} format={format} />
      ) : (
        <ul className="divide-y divide-ink-700/60">
          {schedule.rows.slice(1).map((row) => {
            const result = schedule.perCity.get(row.city.id)
            if (!result) return null
            return (
              <li key={row.city.id} className="flex flex-col gap-2 py-3 first:pt-0 last:pb-0 sm:flex-row sm:items-center">
                <div className="flex items-baseline gap-2 sm:w-48 sm:shrink-0">
                  <span className="font-medium text-ink-100">{row.city.name}</span>
                  <HourCount count={result.hours.length} />
                </div>
                {result.hours.length > 0 ? (
                  <RangeBadges ranges={result.ranges} format={format} />
                ) : (
                  <Warning>No shared awake hours with {reference.city.name}.</Warning>
                )}
              </li>
            )
          })}
        </ul>
      )}
    </Card>
  )
}

function MeetingSummary({
  result,
  cityCount,
  format,
}: {
  result: OverlapResult
  cityCount: number
  format: TimeFormat
}) {
  if (result.hours.length === 0) {
    return (
      <Warning>
        No hour when all {cityCount} cities are awake. Try widening the awake window or switching to Base mode.
      </Warning>
    )
  }
  return (
    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:gap-6">
      <div className="flex items-baseline gap-2">
        <span className="tabular text-4xl font-semibold tracking-tight text-mint-300">{result.hours.length}</span>
        <span className="text-sm text-ink-400">
          {result.hours.length === 1 ? 'hour' : 'hours'} when all {cityCount} cities are awake
        </span>
      </div>
      <RangeBadges ranges={result.ranges} format={format} />
    </div>
  )
}

function HourCount({ count }: { count: number }) {
  return (
    <span className="tabular text-xs text-ink-500">
      {count} {count === 1 ? 'hr' : 'hrs'}
    </span>
  )
}

function Warning({ children }: { children: ReactNode }) {
  return (
    <p className="inline-flex items-center gap-2 rounded-lg border border-amber-400/25 bg-amber-400/10 px-3 py-1.5 text-sm text-amber-300">
      <AlertTriangle className="h-4 w-4 shrink-0" aria-hidden />
      {children}

import { CityLabel, RemoveCityButton } from './CityLabel'
import { HourCell } from './HourCell'
import { cn } from '@/lib/cn'
import { HOURS, type Schedule } from '@/lib/overlap'
import { formatCompact, type TimeFormat } from '@/lib/timezone'

interface DesktopGridProps {
  schedule: Schedule
  format: TimeFormat
}

const COLUMNS = 'minmax(11rem, 14rem) repeat(24, minmax(0, 1fr)) 2.25rem'

/** Cities as rows, the reference city's 24 hours as columns. */
export function DesktopGrid({ schedule, format }: DesktopGridProps) {
  const reference = schedule.rows[0]
  if (!reference) return null

  return (
    <div
      role="grid"
      aria-label="Hour-by-hour availability, cities as rows"
      className="grid gap-x-px gap-y-1.5"
      style={{ gridTemplateColumns: COLUMNS }}
    >
      <div role="row" className="contents">
        <div role="columnheader" className="self-end pb-1 text-[11px] font-medium uppercase tracking-wider text-ink-500">
          {reference.city.name} time
        </div>
        {HOURS.map((hour) => {
          const isCurrent = hour === schedule.currentReferenceHour
          return (
            <div
              key={hour}
              role="columnheader"
              className={cn(
                'tabular flex flex-col items-center justify-end gap-1 pb-1 font-mono text-[10px]',
                isCurrent ? 'text-ink-100' : 'text-ink-500',
              )}
            >
              {isCurrent && <span className="h-1 w-1 rounded-full bg-mint-400" aria-hidden />}
              <span>{formatCompact(hour * 60, format)}</span>
            </div>
          )
        })}
        <div role="columnheader" aria-hidden />
      </div>

      {schedule.rows.map((row) => (
        <div key={row.city.id} role="row" className="contents">
          <div role="rowheader" className="flex items-center pr-3">
            <CityLabel row={row} layout="horizontal" />
          </div>
          {row.cells.map((cell) => (
            <HourCell
              key={cell.referenceHour}
              cell={cell}
              cityName={row.city.name}
              referenceName={reference.city.name}
              format={format}
              isCurrent={cell.referenceHour === schedule.currentReferenceHour}
              orientation="row"
            />
          ))}
          <div role="gridcell" className="flex items-center justify-end">
            <RemoveCityButton row={row} />
          </div>
        </div>
      ))}
    </div>
  )
}

import { CityLabel, RemoveCityButton } from './CityLabel'
import { HourCell } from './HourCell'
import { cn } from '@/lib/cn'
import { HOURS, type Schedule } from '@/lib/overlap'
import { formatCompact, type TimeFormat } from '@/lib/timezone'

interface MobileGridProps {
  schedule: Schedule
  format: TimeFormat
}

/** Cities as columns, the reference city's 24 hours as rows. */
export function MobileGrid({ schedule, format }: MobileGridProps) {
  const reference = schedule.rows[0]
  if (!reference) return null

  const columns = `3.25rem repeat(${schedule.rows.length}, minmax(4.25rem, 1fr))`

  return (
    <div className="scrollbar-thin -mx-1 overflow-x-auto px-1">
      <div
        role="grid"
        aria-label="Hour-by-hour availability, cities as columns"
        className="grid gap-x-1.5 gap-y-px"
        style={{ gridTemplateColumns: columns }}
      >
        <div role="row" className="contents">
          <div
            role="columnheader"
            className="sticky left-0 top-0 z-20 flex items-end bg-ink-850 pb-2 text-[10px] font-medium uppercase tracking-wider text-ink-500"
          >
            Ref
          </div>
          {schedule.rows.map((row) => (
            <div
              key={row.city.id}
              role="columnheader"
              className="sticky top-0 z-10 flex flex-col items-center gap-1 bg-ink-850/95 pb-2 backdrop-blur"
            >
              <CityLabel row={row} layout="vertical" />
              <RemoveCityButton row={row} className="h-6 w-6" />
            </div>
          ))}
        </div>

        {HOURS.map((hour) => {
          const isCurrent = hour === schedule.currentReferenceHour
          return (
            <div key={hour} role="row" className="contents">
              <div
                role="rowheader"
                className={cn(
                  'tabular sticky left-0 z-10 flex items-center gap-1 bg-ink-850 pr-1 font-mono text-[10px]',
                  isCurrent ? 'text-ink-100' : 'text-ink-500',
                )}
              >
                {isCurrent && <span className="h-1 w-1 shrink-0 rounded-full bg-mint-400" aria-hidden />}
                {formatCompact(hour * 60, format)}
              </div>
              {schedule.rows.map((row) => (
                <HourCell
                  key={row.city.id}
                  cell={row.cells[hour]}
                  cityName={row.city.name}
                  referenceName={reference.city.name}
                  format={format}
                  isCurrent={isCurrent}
                  orientation="column"
                />
              ))}
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { Globe2 } from 'lucide-react'
import { DesktopGrid } from './DesktopGrid'
import { MobileGrid } from './MobileGrid'
import { Card } from '../ui/Card'
import type { Schedule } from '@/lib/overlap'
import { useAppStore } from '@/store/useAppStore'

interface ScheduleGridProps {
  schedule: Schedule
}

