                )}
                <span>{hourLabel}</span>
              </div>

              {/* City cells for this hour */}
              {schedule.rows.map((row) => (
                <HourCell
                  key={row.city.id}
                  cell={row.cells[hour]}
                  cityName={row.city.name}
                  referenceName={reference.city.name}
                  format={settings.timeFormat}
                  isCurrent={isCurrent}
                  orientation="column"
                />
              ))}
            </div>
          )
        })}
      </div>
    </div>
  )
}

