  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.goto('http://127.0.0.1:9324/');

  console.log('--- TEST 1: Initial state ---');
  let refBadge = await page.locator('span:has-text(\"REF\")').first().innerText();
  console.log('Initial REF badge:', refBadge);

  console.log('--- TEST 2: Switch to Base Mode ---');
  await page.locator('button:has-text(\"Base Mode\")').click();
  await page.waitForTimeout(300);
  let baseSummary = await page.locator('section[aria-label=\"Overlap Summary\"]').innerText();
  console.log('Base Mode summary:\n', baseSummary);

  console.log('--- TEST 3: Promote Geneva to Reference City ---');
  await page.locator('button:has-text(\"Geneva\")').first().click();
  await page.waitForTimeout(300);
  let newSummary = await page.locator('section[aria-label=\"Overlap Summary\"]').innerText();
  console.log('After promoting Geneva:\n', newSummary);

  console.log('--- TEST 4: Open Settings Panel and change awake window ---');
  await page.locator('button:has-text(\"Awake:\")').click();
  await page.waitForTimeout(300);
  const settingsVisible = await page.locator('section[aria-label=\"Availability and Schedule Settings\"]').isVisible();
  console.log('Settings panel visible:', settingsVisible);

  // Click Night Shift preset (10pm - 6am)
  await page.locator('button:has-text(\"Night Shift\")').click();
  await page.waitForTimeout(300);
  let nightSummary = await page.locator('section[aria-label=\"Overlap Summary\"]').innerText();
  console.log('Night shift summary:\n', nightSummary);

  console.log('--- TEST 5: Add a city (Mumbai - fractional UTC+5:30) ---');
  await page.locator('input[placeholder*=\"Add city\"]').fill('Mumbai');
  await page.waitForTimeout(200);
  await page.locator('button:has-text(\"Mumbai\")').click();
  await page.waitForTimeout(300);
  const mumbaiAdded = await page.locator('button:has-text(\"Mumbai\")').isVisible();
  console.log('Mumbai added:', mumbaiAdded);

  console.log('--- TEST 6: Persistence test (Reload page) ---');
  await page.reload();
  await page.waitForTimeout(500);
  const mumbaiStillThere = await page.locator('button:has-text(\"Mumbai\")').isVisible();
  console.log('Mumbai persisted after reload:', mumbaiStillThere);
  const genevaStillRef = await page.locator('text=Availability with Geneva').isVisible();
  console.log('Geneva still base reference:', genevaStillRef);

  console.log('--- TEST 7: Reset to defaults ---');
  await page.locator('button[aria-label=\"Reset to default settings and cities\"]').click();
  await page.waitForTimeout(500);
  const meetingModeActive = await page.locator('text=Common Availability').isVisible();
  console.log('Reset to Meeting Mode:', meetingModeActive);
  const sfIsRefAgain = await page.locator('text=Times shown in San Francisco (REF)').isVisible();
  console.log('SF is reference again:', sfIsRefAgain);

  await browser.close();
  console.log('ALL INTERACTION TESTS PASSED SUCCESSFULLY!');
}

testInteractions().catch((err) => {
  console.error('Test failed:', err);
  process.exit(1);
});
"

